  item("salads", "rocket", L("سلطة جرجير", "Rocket salad"), L("جرجير وطماطم ودبس رمان", "Rocket, tomato and pomegranate molasses"), 80, { tags: ["veg"], prep: 4 });
  item("salads", "fattoush", L("فتوش", "Fattoush"), L("خضار مع عيش محمص وسماق", "Greens with toasted bread and sumac"), 120, { tags: ["veg"], prep: 6 });
  // مقبلات
  item("starters", "hummus", L("حمص", "Hummus"), L("حمص بالطحينة وزيت زيتون", "Hummus with tahini and olive oil"), 95, { tags: ["veg"], prep: 4 });
  item("starters", "taameya", L("طعمية", "Taameya"), L("٦ أقراص فول أخضر", "6 fava falafel"), 75, { groups: [gExtra], tags: ["veg", "popular"], prep: 7 });
